keymap={'title':'cloud_title','save':'cloud_save','restore':'cloud_restore','signedOut':'cloud_signed_out','connecting':'cloud_connecting','syncing':'cloud_syncing','synced':'cloud_synced','pending':'cloud_pending','guest':'cloud_player_guest','account':'cloud_account_title','signOut':'cloud_sign_out','signOutConfirm':'cloud_sign_out_confirm','restoreConfirm':'cloud_restore_confirm','local':'cloud_compare_local','remote':'cloud_compare_remote','coins':'cloud_compare_coins','unlocks':'cloud_compare_unlocks','solved':'cloud_compare_solved','maxLevel':'cloud_compare_max_level','chooseLocal':'cloud_compare_choose_local','chooseCloud':'cloud_compare_choose_remote','comparisonHelp':'cloud_compare_explanation','conflict':'cloud_conflict','unavailable':'cloud_retry_later','invalid':'cloud_invalid_backup','tooLarge':'cloud_backup_too_large','changed':'cloud_progress_changed','accountChanged':'cloud_account_changed','missing':'cloud_no_backup','signIn':'cloud_sign_in_failed','paused':'progress_reset_local_status','signInShort':'cloud_sign_in_short','reset':'progress_reset_title','resetConfirm':'progress_reset_confirm','capacityTitle':'file_backup_save','capacityWarning':'file_backup_capacity_warning','exportFile':'file_backup_save','later':'file_backup_later','fileSave':'file_backup_save','fileRestore':'file_backup_restore','fileNote':'file_backup_note','fileRestoreConfirm':'file_backup_restore_confirm','fileWorking':'file_backup_working','fileSaved':'file_backup_saved','fileRestored':'file_backup_restored','fileSaveError':'file_backup_save_error','fileRestoreError':'file_backup_restore_error','trickCapacity':'trick_backup_capacity','detailCapacity':'trick_level_backup_capacity','exampleCapacity':'example_backup_capacity','localOnlyDetails':'trick_level_backup_local_only'}
columns=['filesTitle','fileNative','linkProvider','providerLinked','linked','linkedElsewhere','accountHelp','linkConfirm','deleteAccount','deleteConfirm']
def load(folder):
 out={}
 for p in folder.glob('strings*.xml'):
  for item in ET.parse(p).getroot().findall('string'):
   out[item.attrib['name']]=''.join(item.itertext()).replace('\\n','\n').replace("\\'", "'").replace('\\u0025','%').replace('\\"','"')
 return out
report={}
for directory in resources.glob('*.lproj'):
 lang=directory.stem
 suffix={'en':'','zh-Hans':'-zh-rCN','zh-Hant':'-zh-rTW','he':'-iw'}.get(lang,'-'+lang)
 values=load(android/('values'+suffix))
 missing=set(keymap.values())-values.keys()
 assert not missing,(lang,missing)
 out={key:re.sub(r'%\d+\$d','%d',values[source]) for key,source in keymap.items()}
 extra=translations[lang].split('|');assert len(extra)==len(columns),lang
 out.update(dict(zip(columns,extra)))
 short=compact[lang].split('|');assert len(short)==5,lang
 out.update(dict(zip(['cloudSection','save','restore','fileSave','fileSummary'],short)))
 out['exportFile']=out['fileSave']
 for key in ['signedOut','signIn','connecting','accountChanged']:
  out[key]=out[key].replace('Google','Apple / Google')
 out['restoreConfirm']=out['restoreConfirm'].replace('Google Play','App Store')
 # Keep the shared pause explanation valid after either reset or file import.
 paused=re.split(r'[.!?。۔]',out['paused'],maxsplit=1)
 if len(paused)==2 and paused[1].strip(): out['paused']=paused[1].strip()
 for key,provider in [('linkGoogle','Google'),('linkApple','Apple')]: out[key]=out['linkProvider'].replace('%@',provider)
 for key,provider in [('googleLinked','Google'),('appleLinked','Apple')]: out[key]=out['providerLinked'].replace('%@',provider)
 interface=directory/'Interface.strings'
 previous=[line for line in interface.read_text().splitlines() if not line.startswith('"cloud.')]
 generated=[json.dumps('cloud.'+k,ensure_ascii=False)+' = '+json.dumps(v,ensure_ascii=False)+';' for k,v in sorted(out.items())]
 interface.write_text('\n'.join(previous+generated)+'\n')
 old=directory/'Cloud.strings'
 if old.exists(): old.unlink()
 report[lang]={'androidStrings':len(keymap),'iosTranslations':len(columns),'total':len(out)}
print(f'Updated {len(report)} Interface tables with cloud.* labels and compact translations.')
